-- =====================================================================
-- SEED CONTOH DATA ANJUNGAN (beranda) — Yayasan Islam Hasan Kafrawi
--
-- Data ini hanya contoh tampilan: seluruh barisnya ditandai info1 = 'CONTOH-ANJUNGAN'
-- supaya mudah dibersihkan. Menjalankan ulang berkas ini IDEMPOTEN (bagian hapus
-- dijalankan lebih dahulu). Departemen warisan "SMK" tidak dihapus, hanya urutan dan
-- datanya yang ikut ditandai.
--
-- Cara pakai:
--   mysql -h 127.0.0.1 -P 3434 -u root -p < SEED-ANJUNGAN-CONTOH.sql
-- Bersihkan dengan:
--   mysql ... -e "SOURCE bagian-hapus-seed.sql"  (potongan di bawah)
-- =====================================================================
START TRANSACTION;

-- --- bersihkan seed lama -------------------------------------------
-- Urutan wajib: turunan lebih dulu, departemen paling akhir (foreign key
-- jbsvcr.gallery -> jbsakad.departemen ikut menghapus baris galeri).
DELETE a FROM jbsakad.aktivitaskalender a
  JOIN jbsakad.kalenderakademik k ON k.replid = a.idkalender
 WHERE k.info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbsakad.kalenderakademik WHERE info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbsakad.tahunajaran WHERE info1 = 'CONTOH-ANJUNGAN';
DELETE gf FROM jbsvcr.galleryfile gf
  JOIN jbsvcr.gallery g ON g.replid = gf.galleryid
 WHERE g.info1 = 'CONTOH-ANJUNGAN' OR gf.info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbsvcr.gallery WHERE info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbsvcr.videocomment WHERE videoid IN (SELECT replid FROM jbsvcr.video WHERE info1 = 'CONTOH-ANJUNGAN');
DELETE FROM jbsvcr.video WHERE info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbsvcr.notesfile WHERE info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbsvcr.notes WHERE info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbssdm.pegawai WHERE info1 = 'CONTOH-ANJUNGAN';
DELETE FROM jbsakad.departemen WHERE info1 = 'CONTOH-ANJUNGAN';

