-- --- 6. catatan Info Sekolah: 2 per unit, semua departemen aktif ----
-- Bagian 3 hanya mencontohi 5 unit; halaman Info Sekolah memfilter kategori ifse
-- per departemen, jadi unit tanpa baris ini tampil kosong.
INSERT INTO jbsvcr.notes
        (departemen, nis, nip, kategori, judul, fjudul, kepada, tema, pesan,
         fprevpesan, fpesan, tautan, tanggal, lastactive, lastread, nread, info1)
SELECT d.departemen, NULL, '101', 'ifse',
       CONCAT(t.judul, ' ', d.departemen), t.judul,
       'Semua warga satuan pendidikan', 'umum', t.pesan,
       LEFT(t.pesan, 120), CONCAT('<p>', t.pesan, '</p>'), '',
       DATE_SUB('2026-10-19 08:00:00', INTERVAL t.umur_hari DAY),
       DATE_SUB('2026-10-19 08:00:00', INTERVAL t.umur_hari DAY),
       DATE_SUB('2026-10-19 08:00:00', INTERVAL t.umur_hari DAY),
       t.nread, 'CONTOH-ANJUNGAN'
  FROM jbsakad.departemen d
 CROSS JOIN (
       SELECT 'Jadwal Penilaian Semester Ganjil' judul, 1 umur_hari, 25 nread,
              'Penilaian semester ganjil dilaksanakan serentak sesuai jadwal yang dibagikan wali kelas. Siswa hadir lima belas menit sebelum sesi dimulai dan membawa kartu ujian.' pesan
   UNION ALL SELECT 'Pengumuman Pembagian Rapor dan Pendaftaran', 3, 41,
              'Pembagian rapor dilakukan pada pertemuan orangtua. Pendaftaran peserta didik baru tahun ajaran berikutnya dibuka segera setelah rapor dibagikan.'
 ) t
 WHERE d.aktif = 1;

-- --- 7. galeri foto: 2 album per unit per kanal (ifse + mading) -----
-- Berkas gambarnya ada di filesharing/anjungan/galeri/2026 dan dipakai bergantian
-- per album (cover = replid mod 4, isi = replid mod 4 + 1).
INSERT INTO jbsvcr.gallery
        (departemen, nis, nip, kategori, judul, fjudul, keterangan, fprevketerangan,
         fketerangan, tanggal, lastactive, lastread, nread, info1)
SELECT d.departemen, NULL, '101', k.kategori,
       CONCAT('Dokumentasi ', t.judul, ' ', d.departemen), t.judul,
       t.keterangan, LEFT(t.keterangan, 120), CONCAT('<p>', t.keterangan, '</p>'),
       DATE_SUB('2026-10-19 09:00:00', INTERVAL t.umur_hari DAY),
       DATE_SUB('2026-10-19 09:00:00', INTERVAL t.umur_hari DAY),
       DATE_SUB('2026-10-19 09:00:00', INTERVAL t.umur_hari DAY),
       t.nread, 'CONTOH-ANJUNGAN'
  FROM jbsakad.departemen d
 CROSS JOIN (SELECT 'ifse' kategori UNION ALL SELECT 'mading' kategori) k
 CROSS JOIN (
       SELECT 'Kegiatan Belajar Mengajar' judul, 2 umur_hari, 30 nread,
              'Foto kegiatan belajar mengajar di kelas pada semester ganjil. Data contoh tampilan anjungan, bukan dokumentasi resmi satuan pendidikan.' keterangan
   UNION ALL SELECT 'Lomba dan Kegiatan Ekstrakurikuler', 6, 44,
              'Foto lomba dan kegiatan ekstrakurikuler siswa di lingkungan satuan pendidikan. Data contoh tampilan anjungan, bukan dokumentasi resmi satuan pendidikan.'
 ) t
 WHERE d.aktif = 1;

INSERT INTO jbsvcr.galleryfile
        (galleryid, filename, filesize, filetype, fileinfo, ffileinfo, width, height,
         location, iscover, info1)
SELECT g.replid, f.filename, f.filesize, 'image/png',
       CONCAT(f.width, ' x ', f.height, ' Pixel'), CONCAT(f.width, ' x ', f.height, ' Pixel'),
       f.width, f.height, 'anjungan/galeri/2026', x.iscover, 'CONTOH-ANJUNGAN'
  FROM jbsvcr.gallery g
 CROSS JOIN (SELECT 1 iscover UNION ALL SELECT 0 iscover) x
  JOIN (
       SELECT 0 idx, 'contoh-kegiatan-01.png' filename, 1271199 filesize, 1024 width, 768 height
   UNION ALL SELECT 1, 'contoh-kegiatan-02.png', 2068280, 1200, 896
   UNION ALL SELECT 2, 'contoh-kegiatan-03.png', 1235538, 1024, 768
   UNION ALL SELECT 3, 'contoh-kegiatan-04.png', 1349273, 1024, 768
 ) f ON f.idx = MOD(g.replid + x.iscover, 4)
 WHERE g.info1 = 'CONTOH-ANJUNGAN';

-- --- 8. video: 1 per unit per kanal (ifse + mading) -----------------
INSERT INTO jbsvcr.video
        (departemen, nis, nip, kategori, judul, fjudul, keterangan, fprevketerangan,
         fketerangan, tanggal, filename, filesize, filetype, fileinfo, ffileinfo,
         location, lastactive, lastread, nread, info1)
SELECT d.departemen, NULL, '101', k.kategori,
       CONCAT(t.judul, ' ', d.departemen), t.judul,
       t.keterangan, LEFT(t.keterangan, 120), CONCAT('<p>', t.keterangan, '</p>'),
       DATE_SUB('2026-10-19 10:00:00', INTERVAL t.umur_hari DAY),
       'contoh-video-kegiatan.mp4', 3221856, 'video/mp4', 'Data contoh anjungan',
       '<p>Data contoh anjungan.</p>', 'anjungan/video/2026',
       DATE_SUB('2026-10-19 10:00:00', INTERVAL t.umur_hari DAY),
       DATE_SUB('2026-10-19 10:00:00', INTERVAL t.umur_hari DAY),
       t.nread, 'CONTOH-ANJUNGAN'
  FROM jbsakad.departemen d
 CROSS JOIN (SELECT 'ifse' kategori UNION ALL SELECT 'mading' kategori) k
 CROSS JOIN (
       SELECT 'Profil Satuan Pendidikan' judul, 2 umur_hari, 18 nread,
              'Video profil singkat satuan pendidikan. Berkas contoh untuk menguji pemutar video anjungan.' keterangan
   UNION ALL SELECT 'Rekaman Kegiatan Harian', 5, 27,
              'Rekaman kegiatan harian siswa di lingkungan satuan pendidikan. Berkas contoh untuk menguji pemutar video anjungan.'
 ) t
 WHERE d.aktif = 1;

-- --- 9. penulis berita contoh: 2 pegawai per unit --------------------
-- Tanpa baris ini semua berita contoh berpenulis sama (nip 101 'Pegawai'), jadi
-- kolom penulis pada kartu beranda tidak teruji per lembaga.
INSERT INTO jbssdm.pegawai
        (nip, nama, bagian, nikah, kelamin, aktif, id_lembaga, keterangan, info1)
SELECT CONCAT('9', LPAD(d.replid, 4, '0'), '1'),
       ELT(MOD(d.urutan, 13) + 1,
           'Dewi Kartika, S.Pd.', 'Rizky Hidayat, S.Kom.', 'Nur Aisyah, S.Pd.I.',
           'Bambang Wijaya, S.Pd.', 'Sri Wahyuni, S.Pd.', 'Fajar Nugroho, M.Pd.',
           'Laila Rahmawati, S.Pd.', 'Hendra Gunawan, S.Pd.', 'Maya Puspita, S.Pd.',
           'Yusuf Maulana, S.Ag.', 'Rina Marlina, S.Pd.', 'Agus Salim, S.Pd.',
           'Tari Pertiwi, S.Pd.'),
       'Non Akademik', 'tak_ada', 'p', 1, d.replid,
       'Penulis berita contoh anjungan', 'CONTOH-ANJUNGAN'
  FROM jbsakad.departemen d
 WHERE d.aktif = 1;

INSERT INTO jbssdm.pegawai
        (nip, nama, bagian, nikah, kelamin, aktif, id_lembaga, keterangan, info1)
SELECT CONCAT('9', LPAD(d.replid, 4, '0'), '2'),
       ELT(MOD(d.urutan + 6, 13) + 1,
           'Anwar Sadat, S.Pd.', 'Fitri Handayani, S.Pd.', 'Slamet Riyadi, S.Pd.',
           'Indah Permatasari, S.Pd.', 'Budi Santoso, M.Pd.', 'Ratna Dewi, S.Pd.',
           'Kamaruddin, S.Pd.I.', 'Yanti Sumiati, S.Pd.', 'Eko Prasetyo, S.Kom.',
           'Siti Rohmah, S.Pd.', 'Dedi Kurniawan, S.Pd.', 'Mega Sari, S.Pd.',
           'Heru Setiawan, S.Pd.'),
       'Non Akademik', 'tak_ada', 'l', 1, d.replid,
       'Penulis mading contoh anjungan', 'CONTOH-ANJUNGAN'
  FROM jbsakad.departemen d
 WHERE d.aktif = 1;

-- Berita ditulis pegawai humas unitnya, mading oleh pembina kesiswaan unit yang sama.
UPDATE jbsvcr.notes n
  JOIN jbsakad.departemen d ON d.departemen = n.departemen
   SET n.nip = CONCAT('9', LPAD(d.replid, 4, '0'), IF(n.kategori = 'mading', '2', '1'))
 WHERE n.info1 = 'CONTOH-ANJUNGAN';

COMMIT;

-- --- verifikasi ----------------------------------------------------
SELECT 'departemen' AS tabel, COUNT(*) AS jumlah FROM jbsakad.departemen WHERE info1 = 'CONTOH-ANJUNGAN-INDUK' OR info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'notes mading', COUNT(*) FROM jbsvcr.notes WHERE kategori = 'mading' AND info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'notes ifse', COUNT(*) FROM jbsvcr.notes WHERE kategori = 'ifse' AND info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'tahunajaran', COUNT(*) FROM jbsakad.tahunajaran WHERE info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'kalender', COUNT(*) FROM jbsakad.kalenderakademik WHERE info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'agenda', COUNT(*) FROM jbsakad.aktivitaskalender WHERE info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'galeri', COUNT(*) FROM jbsvcr.gallery WHERE info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'file galeri', COUNT(*) FROM jbsvcr.galleryfile WHERE info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'video', COUNT(*) FROM jbsvcr.video WHERE info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'penulis contoh', COUNT(*) FROM jbssdm.pegawai WHERE info1 = 'CONTOH-ANJUNGAN'
UNION ALL SELECT 'unit tanpa penulis berita', COUNT(*) FROM jbsakad.departemen d
   WHERE d.aktif = 1
     AND NOT EXISTS (SELECT 1 FROM jbsvcr.notes n
                      JOIN jbssdm.pegawai p ON p.nip = n.nip
                     WHERE n.departemen = d.departemen AND p.info1 = 'CONTOH-ANJUNGAN')
UNION ALL SELECT 'unit tanpa catatan ifse', COUNT(*) FROM jbsakad.departemen d
   WHERE d.aktif = 1
     AND NOT EXISTS (SELECT 1 FROM jbsvcr.notes n WHERE n.kategori = 'ifse' AND n.departemen = d.departemen)
UNION ALL SELECT 'unit tanpa galeri', COUNT(*) FROM jbsakad.departemen d
   WHERE d.aktif = 1
     AND NOT EXISTS (SELECT 1 FROM jbsvcr.gallery g WHERE g.departemen = d.departemen);

